package com.mygo.music;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;
/** Previews are rendered by the same native scenes with the current track, never mock layouts. */
final class ThemeCenter extends Dialog {
 private final ThemedPlayerDialog player;private final ArrayList<Bitmap> images=new ArrayList<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean closed;private LinearLayout cards;private final ArrayList<Button> defaults=new ArrayList<>();
 ThemeCenter(Activity activity,ThemedPlayerDialog player){super(activity);this.player=player;setTitle("播放主题中心");ScrollView scroll=new ScrollView(activity);cards=new LinearLayout(activity);cards.setOrientation(1);cards.setPadding(player.dp(12),0,player.dp(12),player.dp(12));scroll.addView(cards);setContentView(scroll);for(int i=0;i<PlayerThemes.IDS.length;i++){String id=PlayerThemes.IDS[i];LinearLayout card=new LinearLayout(activity);card.setOrientation(1);card.setPadding(0,player.dp(12),0,player.dp(16));ImageView image=new ImageView(activity);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription(PlayerThemes.NAMES[i]+"，当前歌曲实际播放页预览");card.addView(image,new LinearLayout.LayoutParams(-1,player.dp(170)));TextView label=new TextView(activity);label.setText(PlayerThemes.NAMES[i]+"\n"+PlayerThemes.DETAILS[i]);label.setTextSize(14);label.setTextColor(Color.WHITE);card.addView(label);LinearLayout actions=new LinearLayout(activity);Button enter=new Button(activity);enter.setText("进入主题");Button defaultButton=new Button(activity);defaultButton.setText(id.equals(player.prefs.getString("player_default_theme","dynamic"))?"默认主题":"设为默认");defaults.add(defaultButton);actions.addView(enter,new LinearLayout.LayoutParams(0,player.dp(48),1));actions.addView(defaultButton,new LinearLayout.LayoutParams(0,player.dp(48),1));card.addView(actions);enter.setOnClickListener(v->{player.setTheme(id,true);dismiss();});image.setOnClickListener(v->enter.performClick());defaultButton.setOnClickListener(v->{player.prefs.edit().putString("player_default_theme",id).apply();for(Button b:defaults)b.setText(b==defaultButton?"默认主题":"设为默认");});cards.addView(card);worker.execute(()->{Bitmap photo=null;if(player.prefs.getInt(PlayerThemes.key(id,"background_mode"),0)==1)try{photo=PlayerBackground.decode(ThemeBackdrop.photo(activity,id));}catch(Exception ignored){}final Bitmap result=photo;activity.runOnUiThread(()->{if(closed){if(result!=null)result.recycle();return;}try{Bitmap preview=player.preview(id,result);images.add(preview);image.setImageBitmap(preview);}finally{if(result!=null)result.recycle();}});});}setOnShowListener(d->getWindow().setLayout(Math.min(activity.getResources().getDisplayMetrics().widthPixels-player.dp(24),player.dp(520)),Math.min(activity.getResources().getDisplayMetrics().heightPixels-player.dp(32),player.dp(650))));}
 @Override public void dismiss(){if(closed)return;closed=true;worker.shutdownNow();cards.removeAllViews();for(Bitmap b:images)b.recycle();images.clear();super.dismiss();}
}
